@import url('https://fonts.googleapis.com/css2?family=Space+Mono:ital,wght@0,400;0,700;1,400&display=swap');

:root {
  --bg: #c9c5b8;
  --ink: #16150f;
  --mid: #46443a;
  --border: #16150f;
  --accent: #ff4d17;
  --panel: #eae7dd;
  --font: 'Space Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;
  --pad-x: clamp(20px, 5vw, 64px);
  --pad-top: clamp(20px, 5vw, 64px);
}

body {
  background-color: var(--bg);
  background-image: radial-gradient(rgba(22, 21, 15, 0.30) 0.5px, transparent 0.7px);
  background-size: 4px 4px;
  color: var(--ink);
  font-family: var(--font);
}

/* Fake system menu bar */
body::before {
  content: '\25C9   Elliott OS      File    Edit    View    Special';
  position: fixed; top: 0; left: 0; right: 0; height: 26px;
  display: flex; align-items: center; padding: 0 14px;
  background: var(--panel); border-bottom: 2px solid var(--ink);
  font-size: 12px; letter-spacing: 1px; color: var(--ink);
  white-space: nowrap; overflow: hidden; z-index: 9995;
}
/* Marching loading ticker */
body::after {
  content: ''; position: fixed; left: 0; right: 0; bottom: 0; height: 6px;
  background: repeating-linear-gradient(-45deg, #16150f 0 8px, #ff4d17 8px 16px);
  background-size: 22px 100%;
  animation: lofiMarch 0.5s linear infinite; z-index: 9995;
}
@keyframes lofiMarch { from { background-position: 0 0; } to { background-position: 22px 0; } }

/* The page becomes a system window */
.doc {
  position: relative;
  margin-top: 46px;
  padding: 46px clamp(20px, 4vw, 44px) 48px;
  background: var(--panel);
  border: 2px solid var(--ink);
  box-shadow: 6px 6px 0 var(--ink);
}
.doc::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 26px;
  background: repeating-linear-gradient(var(--ink) 0 1px, transparent 1px 3px);
  border-bottom: 2px solid var(--ink);
}
.doc::after {
  content: '\25D7  elliott.sys'; position: absolute; top: 0; left: 16px; height: 26px;
  display: flex; align-items: center; padding: 0 10px;
  background: var(--panel); color: var(--ink);
  font-size: 12px; font-weight: 700; letter-spacing: 1px;
}

.doc h1 {
  display: inline-block; background: var(--ink); color: var(--panel);
  padding: 2px 12px; font-family: var(--font); font-weight: 700;
  letter-spacing: -1px; line-height: 1.35;
  font-size: clamp(26px, 5vw, 42px);
}
.doc-head .doc-subhead {
  font-style: normal; font-weight: 700; color: var(--ink); font-family: var(--font);
}
.doc-lead p, .doc p { color: var(--ink); font-family: var(--font); }
.doc h2 { color: var(--mid); font-family: var(--font); }
.doc h2::before { content: '\25BA  '; color: var(--accent); }

.doc a { color: var(--accent); text-decoration: underline; text-underline-offset: 2px; }
.doc a:hover { background: var(--accent); color: var(--panel); text-decoration: none; opacity: 1; }

.doc-item { border-left: 3px solid var(--accent); padding-left: 12px; }
.doc-url a { font-weight: 700; }
.doc-contact { color: var(--mid); }

/* Project page viewers */
.doc-pages-toggle { color: var(--accent); }
.doc-pages-track { border: 2px solid var(--ink); border-radius: 0; }
.doc-pages-btn { border: 2px solid var(--ink); border-radius: 0; color: var(--ink); }
.doc-pages-btn:hover:not(:disabled) { background: var(--ink); color: var(--panel); border-color: var(--ink); }
.doc-pages-count { color: var(--mid); }

/* Footer window */
footer {
  border: 2px solid var(--ink); background: var(--panel);
  box-shadow: 5px 5px 0 var(--ink);
  margin: 22px var(--pad-x) calc(var(--console-height, 72px) + 12px);
  width: auto;
}
.footer-nav a { color: var(--ink); }
.footer-nav a:hover { color: var(--accent); }
.theme-toggle { border: 2px solid var(--ink); color: var(--ink); border-radius: 0; }
.theme-toggle:hover { background: var(--ink); color: var(--panel); border-color: var(--ink); }
.toggle-pip { background: var(--accent); border-radius: 0; }

/* Contact popup as a dialog window */
.popup-overlay { background: rgba(22, 21, 15, 0.35); }
.popup-card {
  top: 50%; left: 50%; right: auto; transform: translate(-50%, -50%);
  width: min(440px, calc(100vw - 40px));
  background: var(--panel); border: 2px solid var(--ink);
  box-shadow: 8px 8px 0 var(--ink); border-radius: 0;
  padding: 36px 26px 24px;
}
.popup-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; height: 24px;
  background: repeating-linear-gradient(var(--ink) 0 1px, transparent 1px 3px);
  border-bottom: 2px solid var(--ink);
}
.popup-title { color: var(--ink); font-weight: 700; }
.popup-sub { color: var(--mid); }
.popup-sub a { color: var(--accent); }
.popup-form input, .popup-form textarea {
  border: 2px solid var(--ink); background: #ffffff; color: var(--ink);
  padding: 8px; margin-bottom: 10px;
}
.popup-form input:focus, .popup-form textarea:focus { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent); }
.btn-submit {
  background: var(--accent); color: var(--panel); border: 2px solid var(--ink);
  box-shadow: 3px 3px 0 var(--ink); padding: 8px 18px; text-decoration: none;
  cursor: pointer; font-family: var(--font); font-weight: 700;
}
.btn-submit:hover { transform: translate(-1px, -1px); box-shadow: 4px 4px 0 var(--ink); opacity: 1; }
.btn-close { color: var(--ink); }

/* Chunky scrollbar */
::-webkit-scrollbar { width: 12px; height: 12px; }
::-webkit-scrollbar-track { background: var(--panel); border-left: 2px solid var(--ink); }
::-webkit-scrollbar-thumb { background: var(--ink); border: 2px solid var(--panel); }

