(function () {
  const canvas = document.createElement('canvas');
  canvas.style.cssText = 'position:fixed;top:0;left:0;width:100vw;height:100vh;pointer-events:none;z-index:9990;';
  document.body.appendChild(canvas);
  const ctx = canvas.getContext('2d');

  const INK = '#16150f', ACCENT = '#ff4d17';
  let W, H;
  function resize() { W = canvas.width = window.innerWidth; H = canvas.height = window.innerHeight; }
  resize();
  window.addEventListener('resize', resize);

  // Monochrome "window" bits drifting across the desktop.
  const bits = Array.from({ length: 11 }, (_, i) => ({
    x: Math.random() * window.innerWidth,
    y: Math.random() * window.innerHeight,
    vx: -0.15 - Math.random() * 0.4,
    vy: -0.1 - Math.random() * 0.3,
    w: 24 + Math.random() * 40,
    accent: i % 4 === 0,
  }));

  // Clicks pop an expanding window outline.
  const pops = [];
  function onClick(e) { pops.push({ x: e.clientX, y: e.clientY, r: 6, life: 1 }); }
  window.addEventListener('click', onClick);

  let rafId;
  function loop() {
    ctx.clearRect(0, 0, W, H);

    bits.forEach(b => {
      b.x += b.vx; b.y += b.vy;
      if (b.x < -b.w) { b.x = W + b.w; b.y = Math.random() * H; }
      if (b.y < -b.w) { b.y = H + b.w; b.x = Math.random() * W; }
      const h = b.w * 0.72;
      ctx.save();
      ctx.globalAlpha = 0.4;
      ctx.lineWidth = 2;
      ctx.strokeStyle = INK;
      ctx.strokeRect(b.x, b.y, b.w, h);
      ctx.fillStyle = b.accent ? ACCENT : INK;
      ctx.globalAlpha = b.accent ? 0.45 : 0.22;
      ctx.fillRect(b.x, b.y, b.w, 5);
      ctx.restore();
    });

    for (let i = pops.length - 1; i >= 0; i--) {
      const p = pops[i];
      ctx.save();
      ctx.globalAlpha = p.life * 0.8;
      ctx.lineWidth = 2;
      ctx.strokeStyle = ACCENT;
      ctx.strokeRect(p.x - p.r, p.y - p.r, p.r * 2, p.r * 2);
      ctx.restore();
      p.r += 5; p.life -= 0.05;
      if (p.life <= 0) pops.splice(i, 1);
    }

    rafId = requestAnimationFrame(loop);
  }
  loop();

  window.__aiCleanup = window.__aiCleanup || [];
  window.__aiCleanup.push(() => {
    cancelAnimationFrame(rafId);
    window.removeEventListener('click', onClick);
    window.removeEventListener('resize', resize);
    if (canvas.parentNode) canvas.parentNode.removeChild(canvas);
  });
})();
